---
import Layout from '../layouts/Layout.astro';
import {
  readContact,
  successMessage,
  validateContact,
  type ContactErrors,
  type ContactValues,
} from '../lib/contact';

let values: ContactValues = { name: '', email: '', message: '' };
let errors: ContactErrors = {};
let success = '';

if (Astro.request.method === 'POST') {
  try {
    values = readContact(await Astro.request.formData());
  } catch {
    // Unreadable body: validate the empty values.
  }
  errors = validateContact(values);
  const ok = Object.keys(errors).length === 0;
  if (ok) success = successMessage(values.name);

  if (Astro.request.headers.get('accept') === 'application/json') {
    return Response.json({ ok, errors, message: success }, { status: ok ? 200 : 400 });
  }
  if (ok) values = { name: '', email: '', message: '' };
  else Astro.response.status = 400;
}
---

<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <p id="contact-success" class="success" role="status">{success}</p>
  <form id="contact-form" method="post" action="/contact" novalidate>
    <div class="field">
      <label for="name">Name</label>
      <input
        id="name"
        name="name"
        type="text"
        autocomplete="name"
        value={values.name}
        aria-describedby="name-error"
        aria-invalid={errors.name ? 'true' : undefined}
      />
      <p id="name-error" class="error">{errors.name}</p>
    </div>
    <div class="field">
      <label for="email">Email</label>
      <input
        id="email"
        name="email"
        type="email"
        autocomplete="email"
        value={values.email}
        aria-describedby="email-error"
        aria-invalid={errors.email ? 'true' : undefined}
      />
      <p id="email-error" class="error">{errors.email}</p>
    </div>
    <div class="field">
      <label for="message">Message</label>
      <textarea
        id="message"
        name="message"
        rows="6"
        aria-describedby="message-error"
        aria-invalid={errors.message ? 'true' : undefined}>{values.message}</textarea
      >
      <p id="message-error" class="error">{errors.message}</p>
    </div>
    <button type="submit">Send</button>
  </form>
</Layout>

<script>
  import { readContact, successMessage, validateContact, type ContactErrors } from '../lib/contact';

  const form = document.querySelector<HTMLFormElement>('#contact-form');
  const status = document.querySelector<HTMLElement>('#contact-success');
  const fields = ['name', 'email', 'message'] as const;

  function showErrors(errors: ContactErrors) {
    for (const field of fields) {
      const message = errors[field] ?? '';
      const error = document.querySelector<HTMLElement>(`#${field}-error`);
      const input = form?.elements.namedItem(field);
      if (error) error.textContent = message;
      if (input instanceof HTMLElement) {
        if (message) input.setAttribute('aria-invalid', 'true');
        else input.removeAttribute('aria-invalid');
      }
    }
  }

  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (status) status.textContent = '';
    const data = new FormData(form);
    const values = readContact(data);
    const errors = validateContact(values);
    showErrors(errors);
    if (Object.keys(errors).length > 0) return;

    try {
      const response = await fetch(form.action, {
        method: 'POST',
        body: data,
        headers: { Accept: 'application/json' },
      });
      const result: { ok: boolean; errors?: ContactErrors; message?: string } =
        await response.json();
      if (result.ok) {
        form.reset();
        if (status) status.textContent = result.message || successMessage(values.name);
      } else {
        showErrors(result.errors ?? {});
      }
    } catch {
      if (status) status.textContent = 'Something went wrong. Please try again.';
    }
  });
</script>

<style>
  .field {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    margin-bottom: 1rem;
  }
  .error {
    color: #b00020;
    margin: 0;
    min-height: 1.5em;
  }
  .success:empty {
    display: none;
  }
</style>
EOF
